[
  {
    "statement": "A study in Canada found that agricultural landscapes with smaller fields had higher activity of six of seven bat species.",
    "citations": [
      "1939"
    ]
  },
  {
    "statement": "One study in the UK found that retaining riparian buffers on agricultural land did not affect pipistrelle activity.",
    "citations": [
      "2284"
    ]
  },
  {
    "statement": "No studies were found on the effect of retaining existing in-field trees on bat populations.",
    "citations": [
      "1945"
    ]
  },
  {
    "statement": "No studies were found on the effect of retaining remnant forest or woodland on bat populations.",
    "citations": [
      "1947"
    ]
  },
  {
    "statement": "No studies were found on the effect of planting new hedges on bat populations.",
    "citations": [
      "1942"
    ]
  },
  {
    "statement": "No studies were found on the effect of planting in-field trees on bat populations.",
    "citations": [
      "1946"
    ]
  }
]

[
  {
    "statement": "Several forestry management practices have been studied for their impact on bat populations during logging operations.",
    "citations": []
  },
  {
    "statement": "One review in the Neotropics found that reduced-impact logging had a smaller effect on bat abundance compared to conventional logging.",
    "citations": [
      "989"
    ]
  },
  {
    "statement": "A study in Italy reported greater bat activity in two out of three sites where selective logging was used to open the forest canopy.",
    "citations": [
      "989"
    ]
  },
  {
    "statement": "A study in Germany found similar bat activity and diversity in selectively and conventionally logged forests.",
    "citations": [
      "989"
    ]
  },
  {
    "statement": "A study in Trinidad noted that the composition of bat species was different between selectively logged and conventionally logged forests.",
    "citations": [
      "989"
    ]
  },
  {
    "statement": "Retaining forested corridors in logged areas has been studied.",
    "citations": []
  },
  {
    "statement": "One study in the USA found that bat activity was significantly higher along the edges of forested corridors compared to the interiors of the corridors or adjacent logged areas.",
    "citations": [
      "996"
    ]
  },
  {
    "statement": "A study observed that Seminole bats were more likely to roost in forested corridors than in logged stands or mature forest.",
    "citations": [
      "996"
    ]
  },
  {
    "statement": "Another study found more male but fewer female evening bats roosting in corridors compared to logged stands.",
    "citations": [
      "996"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects of protecting roost trees during forest operations on bat populations.",
    "citations": [
      "1982",
      "2028"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects of retaining buffer zones around core habitats on bat populations.",
    "citations": [
      "1982",
      "2028"
    ]
  }
]

[
  {
    "statement": "No studies were found that evaluated the effects of releasing captive-bred bats on bat populations.",
    "citations": [
      "2039"
    ]
  },
  {
    "statement": "Eight studies evaluated the effects of breeding bats in captivity.",
    "citations": [
      "2053"
    ]
  },
  {
    "statement": "Six studies found that between 6% and 100% of female bats captured in the wild successfully conceived, gave birth, and reared young in captivity.",
    "citations": [
      "2053"
    ]
  },
  {
    "statement": "Seven studies found that 20-100% of bat pups born in captivity survived from between 10 days to adulthood.",
    "citations": [
      "2053"
    ]
  },
  {
    "statement": "One study found that two of five New Zealand lesser short-tailed bat pups born in captivity survived.",
    "citations": [
      "2053"
    ]
  },
  {
    "statement": "The two surviving New Zealand lesser short-tailed bat pups were hand-reared.",
    "citations": [
      "2053"
    ]
  }
]

[
  {
    "statement": "No studies were found that evaluated the effects of educating the public to improve the perception of bats to improve behaviour towards bats.",
    "citations": [
      "1000"
    ]
  },
  {
    "statement": "A review of programmes in the USA and Canada argues that education was not sufficient to change behaviour.",
    "citations": [
      "162"
    ]
  },
  {
    "statement": "A review of programmes in the USA and Canada argues that education was necessary as a catalytic factor for economic incentives and law enforcement.",
    "citations": [
      "162"
    ]
  },
  {
    "statement": "Two studies, one in Estonia and one in the UK, found that raising public awareness, along with other interventions, increased the numbers of natterjack toads.",
    "citations": []
  },
  {
    "statement": "Two studies, one in Estonia and one in the UK, found that raising public awareness, along with other interventions, created 1,023 ponds for amphibians.",
    "citations": []
  },
  {
    "statement": "A study in Mexico found that raising awareness among tourists increased the tourists' knowledge of axolotls.",
    "citations": [
      "831"
    ]
  },
  {
    "statement": "A study in Taiwan found that holding press conferences to publicize frog conservation had no effect on a green tree frog project.",
    "citations": [
      "831"
    ]
  }
]

[
  {
    "statement": "No studies were found that evaluated the cost-effectiveness of creating artificial bat roosts.",
    "citations": []
  },
  {
    "statement": "A study in the UK found that the number of bats using an artificial hibernaculum increased in each of the nine years after the hibernaculum was built.",
    "citations": [
      "2049"
    ]
  },
  {
    "statement": "Another study in the UK found that an artificial cave was used by a small number of brown long-eared bats.",
    "citations": [
      "2049"
    ]
  },
  {
    "statement": "Three studies in Germany and the UK found that artificial hibernacula were used by up to four bat species.",
    "citations": [
      "2049"
    ]
  },
  {
    "statement": "A study in the UK found that a roost reinstated by attaching a felled tree trunk to a nearby tree continued to be used by common noctule bats as a maternity roost.",
    "citations": [
      "2048"
    ]
  },
  {
    "statement": "A review in the USA found that bat houses provided as alternative roosts during bridge replacement works were used by fewer Mexican free-tailed bats than the original roost at one site.",
    "citations": [
      "2942"
    ]
  },
  {
    "statement": "A review in the USA found that bat houses provided as alternative roosts during bridge replacement works were not used by bats at all at three sites.",
    "citations": [
      "2942"
    ]
  },
  {
    "statement": "Two replicated studies in the USA and UK found that bats did not use any of the alternative roosts provided in bat houses or a purpose-built bat wall after exclusion from buildings.",
    "citations": [
      "949"
    ]
  },
  {
    "statement": "Three studies in the USA and UK and one review in the UK found that bat boxes or bat lofts/barns were used by bats at 13-74% of development sites.",
    "citations": [
      "949"
    ]
  },
  {
    "statement": "Bat lofts/barns were used by maternity colonies at one of 19 development sites.",
    "citations": [
      "949"
    ]
  },
  {
    "statement": "Three of five before-and-after studies in Portugal, Ireland, Spain and the UK found that bat colonies used purpose-built roosts in higher or similar numbers after the original roosts were destroyed.",
    "citations": [
      "949"
    ]
  },
  {
    "statement": "Two of five before-and-after studies found that bats used purpose-built roosts in lower numbers than the original roost.",
    "citations": [
      "949"
    ]
  },
  {
    "statement": "A review in the UK found that new bat boxes or lofts built to replace destroyed roosts were four times less likely to be used by returning bats than roosts retained during development.",
    "citations": [
      "949"
    ]
  },
  {
    "statement": "A review in the USA found that spaces created in road bridges for roosting bats to replace those lost during bridge works were recolonized by bats in similar or greater numbers to the original roosts at four of eight sites.",
    "citations": [
      "1967"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects on bat populations of providing artificial subterranean bat roosts to replace roosts in reclaimed mines or disturbed caves.",
    "citations": [
      "974",
      "1005"
    ]
  },
  {
    "statement": "No evidence was found for the effects on farmland wildlife of providing bat boxes, bat grilles or improvements to roosts.",
    "citations": [
      "95"
    ]
  }
]
